//! Tests only: the four places a §8.5 command has to be listed must agree,
//! or the command is rejected at run time with "not allowed by ACL" while
//! every other test still passes. That is how `get_diagnostics()` shipped
//! dead in efaecac (the 2026-11-18 review, finding 1).
//!
//! The lists are read from the real files, not restated here:
//!
//! - `generate_handler!` in `main.rs` (what Tauri will route),
//! - `COMMANDS` in `build.rs` (what the app manifest declares),
//! - `permissions/autogenerated/*.toml` (what `tauri_build` generated from
//!   `COMMANDS`),
//! - `capabilities/*.json` (which window may invoke what),
//! - and the UI's own `"<command>"` literals, per window folder.
//!
//! What it does not catch: a command the UI invokes under a name it builds
//! at run time (nothing does today), a capability granted to a window that
//! doesn't exist, and whether the command does the right thing. It also
//! can't see a `permissions/autogenerated` file left behind by a command
//! that was renamed, since that folder is generated and not in the
//! repository: only "every command has one" is checked.

use std::collections::BTreeSet;
use std::path::{Path, PathBuf};

fn root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
}

fn read(path: &Path) -> String {
    std::fs::read_to_string(path).unwrap_or_else(|e| panic!("{}: {e}", path.display()))
}

/// The text between `open` and the first `close` after it.
fn between<'a>(text: &'a str, open: &str, close: &str) -> &'a str {
    let rest = text.split_once(open).expect(open).1;
    rest.split_once(close).expect(close).0
}

/// Every string literal in `text`, in order.
fn literals(text: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut rest = text;
    while let Some((_, after)) = rest.split_once('"') {
        let (value, tail) = after.split_once('"').expect("a closing quote");
        out.push(value.to_owned());
        rest = tail;
    }
    out
}

/// `COMMANDS` in `build.rs`: what the app manifest declares, and so what
/// `tauri_build` generates an `allow-*` permission for.
fn declared() -> BTreeSet<String> {
    let text = read(&root().join("build.rs"));
    let list = between(&text, "const COMMANDS: &[&str] = &[", "];");
    let set: BTreeSet<String> = literals(list).into_iter().collect();
    assert_eq!(set.len(), literals(list).len(), "a duplicate in COMMANDS");
    set
}

/// The commands `generate_handler!` routes, from `main.rs`.
fn routed() -> BTreeSet<String> {
    let text = read(&root().join("src").join("main.rs"));
    let list = between(&text, "tauri::generate_handler![", "]");
    let names: Vec<String> = (list.split(','))
        .map(|s| s.split("//").next().unwrap_or(s).trim().to_owned())
        .filter(|s| !s.is_empty())
        .collect();
    let set: BTreeSet<String> = names.iter().cloned().collect();
    assert_eq!(set.len(), names.len(), "a duplicate in generate_handler!");
    assert!(
        names.iter().all(|n| n
            .bytes()
            .all(|c| c == b'_' || c.is_ascii_lowercase() || c.is_ascii_digit())),
        "not a plain command name: {names:?}"
    );
    set
}

/// `allow-<kebab>`, the identifier `tauri_build` generates for a command.
fn allow(command: &str) -> String {
    format!("allow-{}", command.replace('_', "-"))
}

struct Capability {
    file: String,
    windows: Vec<String>,
    /// The app's own `allow-*` permissions, without Tauri's `core:` ones.
    allowed: BTreeSet<String>,
}

fn capabilities() -> Vec<Capability> {
    let dir = root().join("capabilities");
    let mut out = Vec::new();
    for entry in std::fs::read_dir(&dir).expect("capabilities").flatten() {
        let path = entry.path();
        if path.extension().and_then(|e| e.to_str()) != Some("json") {
            continue;
        }
        let v: serde_json::Value = serde_json::from_str(&read(&path)).expect("valid JSON");
        let strings = |key: &str| -> Vec<String> {
            (v[key].as_array().unwrap_or(&Vec::new()).iter())
                .filter_map(|x| x.as_str().map(str::to_owned))
                .collect()
        };
        out.push(Capability {
            file: path.file_name().unwrap().to_string_lossy().into_owned(),
            windows: strings("windows"),
            allowed: (strings("permissions").into_iter())
                .filter(|p| !p.contains(':'))
                .collect(),
        });
    }
    assert!(out.len() >= 2, "the strip and settings capabilities");
    out
}

/// Every `.ts`/`.tsx` file under `dir`, skipping tests, visual tests, the
/// dev mock and `node_modules`.
fn sources(dir: &Path, out: &mut Vec<PathBuf>) {
    for entry in std::fs::read_dir(dir).expect("a UI folder").flatten() {
        let path = entry.path();
        let name = entry.file_name().to_string_lossy().into_owned();
        if entry.file_type().is_ok_and(|t| t.is_dir()) {
            if !matches!(name.as_str(), "node_modules" | "visual" | "dev") {
                sources(&path, out);
            }
        } else if (name.ends_with(".ts") || name.ends_with(".tsx")) && !name.contains(".test.") {
            out.push(path);
        }
    }
}

/// The commands whose name appears as a string literal in one window's UI.
fn invoked_by(folder: &str, commands: &BTreeSet<String>) -> BTreeSet<String> {
    let dir = root().join("..").join("ui").join(folder);
    let mut files = Vec::new();
    sources(&dir, &mut files);
    assert!(!files.is_empty(), "no sources under ui/{folder}");
    let text: String = files.iter().map(|f| read(f)).collect();
    (commands.iter())
        .filter(|c| text.contains(&format!("\"{c}\"")))
        .cloned()
        .collect()
}

/// The reason `get_diagnostics()` was unreachable in a built app: the
/// command was routed but neither declared in the app manifest nor granted
/// to the settings window, so Tauri answered every invoke with "Command
/// get_diagnostics not allowed by ACL".
#[test]
fn every_command_is_declared_generated_and_granted() {
    let declared = declared();
    assert_eq!(
        routed(),
        declared,
        "generate_handler! and build.rs COMMANDS"
    );
    // What `tauri_build` generated from COMMANDS, in this build.
    let generated = root().join("permissions").join("autogenerated");
    for c in &declared {
        let file = generated.join(format!("{c}.toml"));
        let toml = read(&file);
        assert!(
            toml.contains(&format!("identifier = \"{}\"", allow(c))),
            "{c}"
        );
        assert!(toml.contains(&format!("commands.allow = [\"{c}\"]")), "{c}");
    }
    // Every grant names a real command, and every command is granted to
    // some window: a command no window may invoke is dead code.
    let caps = capabilities();
    let mut granted = BTreeSet::new();
    for cap in &caps {
        for p in &cap.allowed {
            let command = (declared.iter())
                .find(|c| &allow(c) == p)
                .unwrap_or_else(|| panic!("{}: {p} is not a §8.5 command", cap.file));
            granted.insert(command.clone());
        }
    }
    assert_eq!(granted, declared, "a command no window can invoke");
}

/// The window half: what each window's UI invokes must be granted to that
/// window, and nothing else may be.
#[test]
fn each_window_is_granted_exactly_what_its_ui_invokes() {
    let declared = declared();
    let caps = capabilities();
    let of = |window: &str| {
        (caps.iter())
            .find(|c| c.windows.iter().any(|w| w == window))
            .unwrap_or_else(|| panic!("no capability for the {window} window"))
    };
    // The overlay is the strip window; settings and setup share one window.
    for (folder, window) in [("overlay", "strip"), ("settings", "settings")] {
        let cap = of(window);
        for command in invoked_by(folder, &declared) {
            assert!(
                cap.allowed.contains(&allow(&command)),
                "ui/{folder} invokes {command}, but {} doesn't grant it",
                cap.file
            );
        }
    }
    // Copy diagnostics, the case that was missing (ADR 0038).
    assert!(
        invoked_by("settings", &declared).contains("get_diagnostics"),
        "the Settings UI no longer invokes get_diagnostics"
    );
    assert!(of("settings").allowed.contains("allow-get-diagnostics"));
    // The strip never gets the setup, health, diagnostics or Repair
    // commands, whatever is added later (§11: the overlay only draws).
    let strip = of("strip");
    for command in &declared {
        let settings_only = command.starts_with("setup_")
            || matches!(
                command.as_str(),
                "run_health_check" | "get_diagnostics" | "repair_server" | "play_test_knock"
            );
        assert!(
            !(settings_only && strip.allowed.contains(&allow(command))),
            "the strip must not be granted {command}"
        );
    }
}
